class StdioBridgeTest {
    @Test fun aSealedPlanSizedCallAndTheFollowingCallCrossTheBridgeUnchanged() = runBlocking {
        val call = buildJsonObject {
            put("jsonrpc", "2.0"); put("id", 1); put("method", "tools/call")
            putJsonObject("params") {
                put("name", "kernel")
                putJsonObject("arguments") {
                    put("operation", "build.run")
                    putJsonObject("arguments") {
                        put("node", "bestbuds:serverImage")
                        putJsonObject("plan") { put("tasks", "x".repeat(980_000)) }
                    }
                }
            }
        }.toString()
        val following = """{"jsonrpc":"2.0","id":2,"method":"ping"}"""
        val received = Collections.synchronizedList(mutableListOf<String>())
        val answers = Collections.synchronizedList(mutableListOf<String>())
        bridgeStdio(exchange = { line ->
            received += line
            buildJsonObject { put("id", Json.parseToJsonElement(line).jsonObject.getValue("id")) }
        }, source = "$call\n$following\n".reader(), output = { answers += it })
        assertEquals(setOf(call, following), received.toSet())
        assertEquals(setOf(1, 2), answers.map { Json.parseToJsonElement(it).jsonObject.getValue("id").jsonPrimitive.int }.toSet())
    }

    @Test fun aRequestAtTheOwnerByteLimitIsAccepted() = runBlocking {
        val prefix = "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"ping\",\"padding\":\""
        val suffix = "\"}"
        val call = prefix + "x".repeat(1_048_576 - prefix.length - suffix.length) + suffix
        var received: String? = null
        bridgeStdio(exchange = { received = it; null }, source = "$call\n".reader(), output = {})
        assertEquals(call, received)
    }

